 1	/**
 2	 * WP-009: New Test Suite — Repository Scope Integration Tests
 3	 *
 4	 * 31 test cases covering repository scope functionality across two layers:
 5	 *
 6	 * Storage layer (KnowledgeStoreManager) — 16 cases:
 7	 *   - repositoryStorePath path generation and reserved-name guard
 8	 *   - addInsight with repository scope (success and missing-repository_name error)
 9	 *   - readRepositoryStore empty and populated
10	 *   - listInsights unfiltered, scope-filtered, and name-filtered
11	 *   - searchInsights with repository_name
12	 *   - updateInsight and deleteInsight with repository scope
13	 *   - moveInsight global→repo, repo→repo, and same-name rejection
14	 *   - origin_plan preservation through add, update, and move
15	 *
16	 * GUI REST handlers (gui/api-knowledge.ts) — 10 cases:
17	 *   - handleListKnowledge with repository_name
18	 *   - handleUpdateKnowledge with repository scope and repository_name
19	 *   - handleDeleteKnowledge with repository scope (success and missing repository_name)
20	 *   - handlePromoteKnowledge from repository (success) and from global (rejection)
21	 *   - handleMoveKnowledge global→repo, repo→repo same-name rejection,
22	 *     missing target_repository_name rejection
23	 *   - scope: 'project' rejection by all handlers
24	 *
25	 * Uses real temp directories (mkdtemp/rm) and KnowledgeStoreManager — no mocks.
26	 * Follows the pattern established in tests/gui/knowledge-api.test.ts.
27	 */
28	
29	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
30	import { mkdtemp, rm } from 'fs/promises';
31	import { join } from 'path';
32	import { tmpdir } from 'os';
33	
34	import {
35	  handleListKnowledge,
36	  handleUpdateKnowledge,
37	  handleDeleteKnowledge,
38	  handlePromoteKnowledge,
39	  handleMoveKnowledge,
40	} from '../../gui/api-knowledge.js';
41	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
42	import type { Insight } from '../../src/schema/knowledge.js';
43	
44	// ---------------------------------------------------------------------------
45	// Helpers
46	// ---------------------------------------------------------------------------
47	
48	/** Build a minimal valid insight input (no id). */
49	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
50	  return {
51	    scope: 'global',
52	    title: 'Default title',
53	    content: 'Default content',
54	    category: 'general',
55	    tags: [],
56	    source: 'test',
57	    created_at: '2026-01-01T00:00:00Z',
58	    confidence: 0.8,
59	    ...overrides,
60	  };
61	}
62	
63	// ---------------------------------------------------------------------------
64	// Storage layer — repositoryStorePath
65	// ---------------------------------------------------------------------------
66	
67	describe('KnowledgeStoreManager.repositoryStorePath', () => {
68	  let ledgerRoot: string;
69	  let manager: KnowledgeStoreManager;
70	
71	  beforeEach(async () => {
72	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-path-'));
73	    manager = new KnowledgeStoreManager(ledgerRoot);
74	  });
75	
76	  afterEach(async () => {
77	    await rm(ledgerRoot, { recursive: true, force: true });
78	  });
79	
80	  it("returns {knowledgeDir}/{repoName}-insights.json for a valid repository name", () => {
81	    const storePath = manager.repositoryStorePath('hcp-editor');
82	    const expected = join(manager.knowledgeDir(), 'hcp-editor-insights.json');
83	    expect(storePath).toBe(expected);
84	  });
85	
86	  it("throws for the reserved name 'global'", () => {
87	    expect(() => manager.repositoryStorePath('global')).toThrow(
88	      "'global' is a reserved name and cannot be used as a repository name."
89	    );
90	  });
91	});
92	
93	// ---------------------------------------------------------------------------
94	// Storage layer — addInsight (repository scope)
95	// ---------------------------------------------------------------------------
96	
97	describe('KnowledgeStoreManager.addInsight — repository scope', () => {
98	  let ledgerRoot: string;
99	  let manager: KnowledgeStoreManager;

101	  beforeEach(async () => {
102	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-add-'));
103	    manager = new KnowledgeStoreManager(ledgerRoot);
104	  });
105	
106	  afterEach(async () => {
107	    await rm(ledgerRoot, { recursive: true, force: true });
108	  });
109	
110	  it('creates repository store file with correct fields including origin_plan', async () => {
111	    const insight = await manager.addInsight(
112	      makeInsightInput({
113	        scope: 'repository',
114	        repository_name: 'hcp-editor',
115	        origin_plan: 'my-plan',
116	        title: 'Codebase insight',
117	      })
118	    );
119	
120	    expect(insight.scope).toBe('repository');
121	    expect(insight.repository_name).toBe('hcp-editor');
122	    expect(insight.origin_plan).toBe('my-plan');
123	    expect(insight.title).toBe('Codebase insight');
124	    expect(insight.id).toBeTypeOf('number');
125	    expect(insight.id).toBeGreaterThan(0);
126	
127	    // Verify the file was written in the correct location
128	    const store = await manager.readRepositoryStore('hcp-editor');
129	    expect(store.insights).toHaveLength(1);
130	    expect(store.insights[0]!.title).toBe('Codebase insight');
131	  });
132	
133	  it('throws when repository_name is absent for repository-scoped insight', async () => {
134	    await expect(
135	      manager.addInsight(
136	        makeInsightInput({ scope: 'repository' /* no repository_name */ })
137	      )
138	    ).rejects.toThrow('repository_name is required for repository-scoped insights');
139	  });
140	});
141	
142	// ---------------------------------------------------------------------------
143	// Storage layer — readRepositoryStore
144	// ---------------------------------------------------------------------------
145	
146	describe('KnowledgeStoreManager.readRepositoryStore', () => {
147	  let ledgerRoot: string;
148	  let manager: KnowledgeStoreManager;
149	
150	  beforeEach(async () => {
151	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-repo-read-'));
152	    manager = new KnowledgeStoreManager(ledgerRoot);
153	  });
154	
155	  afterEach(async () => {
156	    await rm(ledgerRoot, { recursive: true, force: true });
157	  });
158	
159	  it('returns empty store when repository file does not exist', async () => {
160	    const store = await manager.readRepositoryStore('hcp-editor');
161	    expect(store.insights).toEqual([]);
162	    expect(store.next_id).toBe(1);
163	  });
164	
165	  it('returns stored insights after addInsight', async () => {
166	    await manager.addInsight(
167	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'First' })
168	    );
169	    await manager.addInsight(
170	      makeInsightInput({ scope: 'repository', repository_name: 'hcp-editor', title: 'Second' })
171	    );
172	
173	    const store = await manager.readRepositoryStore('hcp-editor');
174	    expect(store.insights).toHaveLength(2);
175	    const titles = store.insights.map((i) => i.title);
176	    expect(titles).toContain('First');
177	    expect(titles).toContain('Second');
178	  });
179	});
180	
181	// ---------------------------------------------------------------------------
182	// Storage layer — listInsights (scope and repository_name filtering)
183	// ---------------------------------------------------------------------------
184	
185	describe('KnowledgeStoreManager.listInsights — repository scope filtering', () => {
186	  let ledgerRoot: string;
