272	/**
273	 * Deletes an existing knowledge insight identified by its numeric ID.
274	 *
275	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
276	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
277	 * query parameter; when `scope === 'repository'`, `repository_name` is also required
278	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
279	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
280	 * multiple stores.
281	 *
282	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
283	 *
284	 * **Defence-in-depth note:** `repository_name` is accepted as a raw query-parameter
285	 * string and is NOT validated against `PROJECT_SLUG_REGEX` at this handler level.
286	 * The storage layer's `_validateSlug()` enforces the regex before constructing any
287	 * file path, making path-traversal attacks impossible in practice. However, because
288	 * `_validateSlug()` throws a generic `Error` (not an `ApiError`), a malformed slug
289	 * will propagate to the server's unhandled-error branch and return HTTP 500 rather
290	 * than a semantically correct HTTP 400 `VALIDATION_ERROR`. Contrast with
291	 * `handleMoveKnowledge` and `handleUpdateKnowledge`, where `repository_name` is
292	 * validated via Zod schema (`z.string().regex(PROJECT_SLUG_REGEX)`) before reaching
293	 * the storage layer. A future hardening pass should add an explicit regex guard here
294	 * (mirroring the Zod pattern) to return a proper 400 and remove reliance on the
295	 * storage layer as the sole validation point for this field.
296	 *
297	 * @param ledgerRoot      Absolute path to the central ledger root.
298	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
299	 * @param scope           Required scope query parameter ('global' or 'repository').
300	 * @param repository_name Required when scope is 'repository'; the repository name.
301	 * @returns `null` — consistent with other delete handlers.
302	 */
303	export async function handleDeleteKnowledge(
304	  ledgerRoot: string,
305	  rawId: string,
306	  scope: string | undefined,
307	  repository_name?: string
308	): Promise<null> {
309	  const id = parseKnowledgeId(rawId);
310	
311	  // Validate scope — required and must be a recognised InsightScope value.
312	  const scopeResult = InsightScope.safeParse(scope);
313	  if (!scopeResult.success) {
314	    validationError('scope query parameter is required and must be "global" or "repository".');
315	  }
316	  const validatedScope = scopeResult.data;
317	
318	  // repository_name is required when scope === 'repository'.
319	  if (validatedScope === 'repository' && !repository_name) {
320	    validationError('repository_name query parameter is required when scope is "repository".');
321	  }
322	
323	  const manager = new KnowledgeStoreManager(ledgerRoot);
324	
325	  try {
326	    await manager.deleteInsight(id, { scope: validatedScope, repository_name });
327	  } catch (err) {
328	    const msg = err instanceof Error ? err.message : String(err);
329	    if (msg.includes('not found')) {
330	      throw new ApiError('NOT_FOUND', 'Insight not found.');
331	    }
332	    throw err;
333	  }
334	
335	  return null;
336	}
