416	/**
417	 * Moves an insight from one scope/repository to a different repository using the
418	 * atomic KnowledgeStoreManager.moveInsight() method.
419	 *
420	 * Supports two move variants:
421	 * - global → repository: moves the global insight into a named repository store
422	 * - repository → repository: moves a repository insight to a different repository
423	 *
424	 * The returned insight is the newly created copy — it has a **different numeric
425	 * ID** (assigned by the target store's `next_id` counter).
426	 *
427	 * @param ledgerRoot  Absolute path to the central ledger root.
428	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
429	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
430	 * @returns The newly created Insight in the target repository store.
431	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
432	 *   or the destination name fails PROJECT_SLUG_REGEX.
433	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
434	 */
435	export async function handleMoveKnowledge(
436	  ledgerRoot: string,
437	  rawId: string,
438	  body: unknown
439	): Promise<Insight> {
440	  const id = parseKnowledgeId(rawId);
441	
442	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
443	  if (!parseResult.success) {
444	    validationError('Invalid knowledge move body.', parseResult.error.issues);
445	  }
446	
447	  const { source_scope, source_repository_name, repository_name } = parseResult.data;
448	
449	  // Require source_repository_name when source_scope is 'repository'.
450	  if (source_scope === 'repository' && !source_repository_name) {

451	    validationError('source_repository_name is required when source_scope is "repository".');
452	  }
453	
454	  // Validate that source and destination are not identical.
455	  // global → repository always changes scope, so no identity check is needed for that case.
456	  if (source_scope === 'repository' && source_repository_name === repository_name) {
457	    validationError('Source and destination repository are identical; nothing to move.');
458	  }
459	
460	  const manager = new KnowledgeStoreManager(ledgerRoot);
461	
462	  try {
463	    return await manager.moveInsight(
464	      id,
465	      { scope: source_scope, repository_name: source_repository_name },
466	      'repository',
467	      repository_name
468	    );
469	  } catch (err) {
470	    const msg = err instanceof Error ? err.message : String(err);
471	    if (msg.toLowerCase().includes('not found')) {
472	      throw new ApiError('NOT_FOUND', 'Insight not found.');
473	    }
474	    throw err;
475	  }
476	}

346	   * @throws Error if targetScope === 'repository' and targetRepositoryName is absent
347	   * @throws Error if source and target resolve to the same store (identity move)
348	   * @warning Do NOT call from inside a withLock(knowledgeDir, …) callback.
349	   *   This method acquires the lock itself; a nested call would deadlock.
350	   */
351	  async moveInsight(
352	    id: number,
353	    sourceFilter: { scope: InsightScope; repository_name?: string },
354	    targetScope: InsightScope,
355	    targetRepositoryName?: string
356	  ): Promise<Insight> {
357	    if (targetScope === 'repository' && !targetRepositoryName) {
358	      throw new Error('targetRepositoryName is required when targetScope is "repository"');
359	    }
360	
361	    // Guard against identity moves: same repository → same repository
362	    if (
363	      sourceFilter.scope === 'repository' &&
364	      targetScope === 'repository' &&
365	      sourceFilter.repository_name !== undefined &&
366	      sourceFilter.repository_name === targetRepositoryName
367	    ) {
368	      throw new Error(
369	        `Cannot move insight to the same repository store: "${targetRepositoryName}"`
370	      );
371	    }
372	
373	    return await withLock(this.knowledgeDir(), async () => {
374	      // 1. Resolve source path(s)
375	      const sourcePaths = await this._storePathsForFilter(sourceFilter);
376	
377	      // 2. Find insight in source store
378	      let sourceStorePath: string | undefined;
379	      let sourceStore: KnowledgeStore | undefined;
380	      let sourceIdx = -1;
381	
382	      for (const storePath of sourcePaths) {
383	        const store = await this._readStore(storePath);
384	        const idx = store.insights.findIndex((i) => i.id === id);
385	        if (idx !== -1) {
386	          sourceStorePath = storePath;
387	          sourceStore = store;
388	          sourceIdx = idx;
389	          break;
390	        }
391	      }
392	
393	      if (!sourceStorePath || !sourceStore || sourceIdx === -1) {
394	        throw new Error(`Insight with id ${id} not found`);
395	      }
396	
397	      const originalInsight = sourceStore.insights[sourceIdx];
398	
399	      // 3. Resolve target store path and read it
400	      const targetStorePath =
401	        targetScope === 'global'
402	          ? this.globalStorePath()
403	          : this.repositoryStorePath(targetRepositoryName!);
404	
405	      const targetStore = await this._readStore(targetStorePath);
406	
407	      // 4. Construct the moved insight with new id, scope, and updated_at
408	      const newNumericId = targetStore.next_id;
409	      targetStore.next_id = newNumericId + 1;
410	      const movedAt = now(); // capture once — reused for both movedInsight.updated_at and store.last_updated
411	
412	      const movedInsight: Insight = InsightSchema.parse({
413	        ...originalInsight,
414	        id: newNumericId,
415	        scope: targetScope,
416	        repository_name: targetScope === 'global' ? undefined : targetRepositoryName,
417	        updated_at: movedAt,
418	      });
419	
420	      // 5. Append to target store and write atomically
421	      targetStore.insights.push(movedInsight);
422	      targetStore.last_updated = movedAt;
423	      const validatedTarget = KnowledgeStoreSchema.parse(targetStore);
424	      await atomicWriteJson(targetStorePath, validatedTarget);

